package com.edunest.backend.modules.topic.repository;
import com.edunest.backend.modules.topic.entity.Topic; import org.springframework.data.jpa.repository.*; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public interface TopicRepository extends JpaRepository<Topic,Long>{ @EntityGraph(attributePaths={"unit","unit.subject"}) List<Topic> findByUnitIdAndActiveTrueOrderByTopicNumberAsc(Long unitId); @EntityGraph(attributePaths={"unit","unit.subject"}) List<Topic> findByUnit_IdInAndActiveTrueOrderByUnit_IdAscTopicNumberAsc(List<Long> unitIds); @EntityGraph(attributePaths={"unit","unit.subject"}) Optional<Topic> findByIdAndActiveTrue(Long id); boolean existsByUnitIdAndTopicNumber(Long unitId,Integer n); boolean existsByUnitIdAndTopicNumberAndIdNot(Long unitId,Integer n,Long id); }